#include <bits/stdc++.h>
using namespace std;
class Solution {vector<int> p,sz;int root(int x){return p[x]==x?x:p[x]=root(p[x]);}public:long long countPairs(int n,vector<vector<int>>& edges){p.resize(n);iota(p.begin(),p.end(),0);sz.assign(n,1);for(auto& e:edges){int a=root(e[0]),b=root(e[1]);if(a!=b){p[a]=b;sz[b]+=sz[a];}}long long ans=0,seen=0;for(int i=0;i<n;++i)if(root(i)==i){ans+=seen*sz[i];seen+=sz[i];}return ans;}};
